-- One language row, written with REAL VALUES rather than the emitter's base-0
-- stub: Language: Chinese at Technical 50/+5, the same convention as
-- Language: Russian and every other ordinary language in this catalog.
--
-- The emitter wrote it at base 0 and filed it under Communications, which is
-- wrong twice against that convention - the same two mistakes it made for
-- Language: Russian when the Night Witch landed.
--
-- This is the ONLY class in the book that grants Chinese rather than Euro. The
-- Slayer is "sometimes confused with the Demon Queller" of Rifts Japan, who the
-- book says is also found in southern and eastern Russia, so he hunts east as
-- well as west.
INSERT OR IGNORE INTO skills (name, category, base, per_level, source, source_book) VALUES ('Language: Chinese', 'Technical', 50, 5, 'import', 'Rifts World Book 18: Mystic Russia p.136-140');


